const rawInput = $attendanceData || '';

// Validate Input
if (!rawInput || typeof rawInput !== 'string') {
  return {
    error: 'attendanceData input is missing or not a string'
  };
}

// Parse Raw Attendance Input
function parseRawAttendance(rawInput) {
  const input = rawInput.trim();
  const chunks = input.split('name:').slice(1); // skip first empty
  return chunks.map(chunk => {
    const record = {};
    const block = 'name:' + chunk;
    const regex = /(\w+):\s*([^\n\r]+)/g;
    let match;
    while ((match = regex.exec(block)) !== null) {
      const key = match[1].trim();
      const val = match[2].trim();
      const num = Number(val);
      record[key] = isNaN(num) ? val : num;
    }
    return record;
  });
}

const records = parseRawAttendance(rawInput);

// === Per-Student Overall + Per-Class Attendance Calculation ===
const studentClassMap = {};
const overallMap = {};

for (const record of records) {
  const id = record.student_id;
  const className = record.class || 'UNKNOWN';
  const key = `${id}_${className}`;

  if (!studentClassMap[key]) {
    studentClassMap[key] = {
      student_id: id,
      name: record.name,
      class: className,
      present: 0,
      remote: 0,
      tardy: 0,
      total: 0,
      canceled: 0
    };
  }

  const s = studentClassMap[key];
  s.present += Number(record.present) || 0;
  s.remote += Number(record.remote) || 0;
  s.tardy += Number(record.tardy) || 0;
  s.total += Number(record.total) || 0;
  s.canceled += Number(record.canceled) || 0;

  if (!overallMap[id]) {
    overallMap[id] = {
      student_id: id,
      name: record.name,
      present: 0,
      remote: 0,
      tardy: 0,
      total: 0,
      canceled: 0,
      classes: []
    };
  }

  const o = overallMap[id];
  o.present += Number(record.present) || 0;
  o.remote += Number(record.remote) || 0;
  o.tardy += Number(record.tardy) || 0;
  o.total += Number(record.total) || 0;
  o.canceled += Number(record.canceled) || 0;
  o.classes.push(s);
}

// === Build Student-Level JSON Output ===
const studentResults = [];

for (const id in overallMap) {
  const s = overallMap[id];
  const attended = s.present + s.remote + 0.5 * s.tardy;
  const adjustedTotal = s.total - s.canceled;
  const absent = Math.max(0, adjustedTotal - attended);
  const percentage = adjustedTotal > 0 ? (attended / adjustedTotal) * 100 : 0;

  studentResults.push({
    student_id: s.student_id,
    name: s.name,
    overall_attendance_percent: Number(percentage.toFixed(2)),
    total: s.total,
    present: s.present,
    remote: s.remote,
    tardy: s.tardy,
    absent: absent,
    canceled: s.canceled,
    classes: s.classes.map(cls => {
      const classAttended = cls.present + cls.remote + 0.5 * cls.tardy;
      const classAdjustedTotal = cls.total - cls.canceled;
      const classAbsent = Math.max(0, classAdjustedTotal - classAttended);
      const classPercentage = classAdjustedTotal > 0 ? (classAttended / classAdjustedTotal) * 100 : 0;
      return {
        class: cls.class,
        class_attendance_percent: Number(classPercentage.toFixed(2)),
        total: cls.total,
        present: cls.present,
        remote: cls.remote,
        tardy: cls.tardy,
        absent: classAbsent,
        canceled: cls.canceled
      };
    })
  });
}

// === Class-Level Aggregation ===
const classStats = {};

for (const rec of records) {
  const className = rec.class || 'UNKNOWN';

  if (!classStats[className]) {
    classStats[className] = {
      students: new Set(),
      total: 0,
      present: 0,
      remote: 0,
      tardy: 0,
      absent: 0,
      canceled: 0
    };
  }

  const stats = classStats[className];
  stats.students.add(rec.student_id);
  stats.total += Number(rec.total) || 0;
  stats.present += Number(rec.present) || 0;
  stats.remote += Number(rec.remote) || 0;
  stats.tardy += Number(rec.tardy) || 0;
  stats.absent += Number(rec.absent) || 0;
  stats.canceled += Number(rec.canceled) || 0;
}

// Format class summaries
const classResults = [];

for (const className in classStats) {
  const stats = classStats[className];
  const adjustedTotal = stats.total - stats.canceled;
  const attended = stats.present + stats.remote + 0.5 * stats.tardy;
  const averageAttendance = adjustedTotal > 0 ? (attended / adjustedTotal) * 100 : 0;

  classResults.push({
    class: className,
    students: stats.students.size,
    total: stats.total,
    present: stats.present,
    remote: stats.remote,
    tardy: stats.tardy,
    absent: stats.absent,
    canceled: stats.canceled,
    average_attendance_percent: Number(averageAttendance.toFixed(2))
  });
}

// Helper to find top class by a given field
function topBy(field) {
  return [...classResults].sort((a, b) => b[field] - a[field])[0];
}

const classSummary = {
  classes_found: classResults.map(r => r.class),
  most_tardies: topBy('tardy'),
  most_absent: topBy('absent'),
  most_canceled: topBy('canceled'),
  most_total_sessions: topBy('total'),
  most_students: topBy('students'),
  highest_avg_attendance: topBy('average_attendance_percent'),
  lowest_avg_attendance: [...classResults].sort((a, b) => a.average_attendance_percent - b.average_attendance_percent)[0],
  all_class_stats: classResults
};

// === Final JSON Output ===
return JSON.stringify({
  class_level_summary: classSummary,
});

